changeSet.sql:
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pgcrypto') THEN
        CREATE EXTENSION pgcrypto;
    END IF;
END;
$$;

DO $$
BEGIN
    DELETE FROM category_item_mapping t
    USING category_item_mapping d
    WHERE t.menu_category_mapping_id = d.menu_category_mapping_id
      AND t.item_id = d.item_id
      AND t.ctid > d.ctid;
END;
$$;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name='category_item_mapping' AND column_name='id'
    ) THEN
        ALTER TABLE public.category_item_mapping ADD COLUMN id UUID;
    END IF;
END;
$$;

DO $$
DECLARE pk_name text;
BEGIN
    SELECT tc.constraint_name INTO pk_name
    FROM information_schema.table_constraints tc
    WHERE tc.table_schema='public' AND tc.table_name='category_item_mapping' AND tc.constraint_type='PRIMARY KEY'
    LIMIT 1;
    IF pk_name IS NOT NULL THEN
        EXECUTE format('ALTER TABLE public.category_item_mapping DROP CONSTRAINT %I', pk_name);
    END IF;
END;
$$;
